# ============================================================
# 3. MERGE WITH LAGS
# ============================================================
merged <- turb |>
  left_join(d_prof |> select(year, prof_pc1),                          by="year") |>
  left_join(d_prof |> select(year, prof_lag1=prof_pc1) |> mutate(year=year+1), by="year") |>
  left_join(d_prof |> select(year, prof_lag2=prof_pc1) |> mutate(year=year+2), by="year")

r_stats <- function(x, y) {
  cc  <- complete.cases(cbind(x, y))
  r   <- cor(x[cc], y[cc])
  n   <- sum(cc)
  tst <- r * sqrt((n-2)/(1-r^2))
  p   <- 2 * pt(-abs(tst), df=n-2)
  list(r=r, n=n, t=tst, p=p)
}

s0 <- r_stats(merged$turb_pc1, merged$prof_pc1)
s1 <- r_stats(merged$turb_pc1, merged$prof_lag1)
s2 <- r_stats(merged$turb_pc1, merged$prof_lag2)

cat(sprintf("Lag 0: r=%.3f, N=%d, p=%.3f\n", s0$r, s0$n, s0$p))
cat(sprintf("Lag 1: r=%.3f, N=%d, p=%.3f\n", s1$r, s1$n, s1$p))
cat(sprintf("Lag 2: r=%.3f, N=%d, p=%.3f\n", s2$r, s2$n, s2$p))

