# ============================================================
# FIGURE 2: THREE SCATTER PLOTS
# ============================================================
make_scatter <- function(x_vec, y_vec, stats, lag_label, x_label, highlight=FALSE) {
  df <- data.frame(x=x_vec, y=y_vec) |> na.omit()
  p_str  <- if(stats$p < 0.001) "p < .001" else sprintf("p = %.3f", stats$p)
  annot  <- sprintf("r = %.3f\n%s\nN = %d", stats$r, p_str, stats$n)

  # Stronger visual treatment for the best-fitting lag
  line_col  <- if(highlight) RED   else "#888888"
  fill_col  <- if(highlight) "#ffd5d5" else "#e0e0e0"
  line_w    <- if(highlight) 1.4   else 0.8
  point_a   <- if(highlight) 0.9   else 0.5
  annot_col <- if(highlight) RED   else GREY
  title_col <- if(highlight) RED   else NAVY
  border_col <- if(highlight) RED  else "grey80"

  ggplot(df, aes(x=x, y=y)) +
    geom_smooth(method="lm", se=TRUE, colour=line_col, fill=fill_col,
                linewidth=line_w, alpha=0.35) +
    geom_point(colour=NAVY, size=3, alpha=point_a) +
    annotate("label", x=-Inf, y=Inf,
             label    = annot,
             hjust    = -0.1, vjust=1.15,
             size     = 4.0, colour=annot_col, fill="white",
             fontface = "bold", lineheight=1.4) +
    labs(
      title    = lag_label,
      x        = x_label,
      y        = "Turbulence PC1"
    ) +
    theme_bw(base_size=11) +
    theme(
      plot.title         = element_text(face="bold", colour=title_col, size=11),
      panel.grid.minor   = element_blank(),
      panel.border       = element_rect(colour=border_col, linewidth=if(highlight) 1.5 else 0.5)
    )
}

p_s0 <- make_scatter(merged$prof_pc1,  merged$turb_pc1, s0,
  "Lag 0 — same year", "Professionalisation PC1 (year t)", highlight=FALSE)
p_s1 <- make_scatter(merged$prof_lag1, merged$turb_pc1, s1,
